#!/bin/sh
# Regenerates AGENTS.md at the repository root from the Rules/ files.
# ~/.vibe/AGENTS.md symlinks to the generated file, so the global Vibe
# context always reflects the current rules.
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root/Rules"

{
  printf '%s\n' \
    '# Agent Rules' \
    '' \
    'Always apply these rules when writing, editing, or reviewing code, and when working with git. This file is loaded globally for every project: `~/.vibe/AGENTS.md` is a symlink to this file.' \
    '' \
    'Generated from the `Rules/` directory in this repository. Do not edit this file directly - edit the source files and run `Rules/sync-agents-md.sh` to regenerate.' \
    '' \
    '---'
  for f in code-style.md software-design-principles.md development-preferences.md git-conventions.md security.md; do
    printf '\n<!-- source: Rules/%s -->\n\n' "$f"
    cat "$f"
    printf '\n---\n'
  done
} > "$root/AGENTS.md"

echo "Regenerated $root/AGENTS.md"
